  if (k === 'raiox') { fmGo('banca'); try { wlSetTab('resumo'); } catch (e) {} setTimeout(() => { const el = document.getElementById('wlRaioX'); if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' }); }, 150); return; }
